//=============================================================================
// tb_dct_top.v
// Rigorous Self-Checking Unit Testbench for Row-Serial dct_top.v
// Tests all HEVC TU sizes (4x4, 8x8, 16x16, 32x32) in Forward & Inverse
// against HM 18.0 reference 2D transform results.
//=============================================================================

`timescale 1ns / 1ps
`include "parameter_pkg.vh"

module tb_dct_top;

    reg clk;
    reg rst_n;

    reg         fwd_inv_n;
    reg  [2:0]  tu_size_log2;
    reg         in_valid;
    wire        in_ready;
    reg  [16383:0] in_data;

    wire        out_valid;
    reg         out_ready;
    wire [16383:0] out_data;
    wire [2:0]  out_tu_size_log2;
    wire        out_fwd_inv_n;

    dct_top uut (
        .clk              (clk),
        .rst_n            (rst_n),
        .fwd_inv_n        (fwd_inv_n),
        .tu_size_log2     (tu_size_log2),
        .in_valid         (in_valid),
        .in_ready         (in_ready),
        .in_data          (in_data),
        .out_valid        (out_valid),
        .out_ready        (out_ready),
        .out_data         (out_data),
        .out_tu_size_log2 (out_tu_size_log2),
        .out_fwd_inv_n    (out_fwd_inv_n)
    );

    always #5 clk = ~clk;

    integer total_tests;
    integer pass_tests;
    integer err_count;

    task check_2d_transform(
        input [31:0]       test_id,
        input              fwd,
        input [2:0]        size_log2,
        input [16383:0]    stim_in,
        input [16383:0]    exp_out
    );
        integer r, c, N;
        reg signed [15:0] act_coeff;
        reg signed [15:0] exp_coeff;
        reg test_fail;
    begin
        N = (1 << size_log2);
        @(posedge clk);
        #1;
        while (!in_ready) @(posedge clk);
        #1;
        fwd_inv_n    = fwd;
        tu_size_log2 = size_log2;
        in_data      = stim_in;
        in_valid     = 1'b1;

        @(posedge clk);
        #1;
        in_valid     = 1'b0;

        @(posedge clk);
        while (!out_valid) @(posedge clk);
        #1;

        test_fail = 0;
        for (r = 0; r < N; r = r + 1) begin
            for (c = 0; c < N; c = c + 1) begin
                act_coeff = out_data[(r*32+c)*16 +: 16];
                exp_coeff = exp_out[(r*32+c)*16 +: 16];
                if (act_coeff !== exp_coeff) begin
                    $display("ERROR [Test %0d] Size=%0dx%0d Fwd=%b @ [%0d][%0d]: Actual=%0d Expected=%0d (diff=%0d)",
                             test_id, N, N, fwd, r, c, act_coeff, exp_coeff, act_coeff - exp_coeff);
                    err_count = err_count + 1;
                    test_fail = 1;
                end
            end
        end

        if (out_tu_size_log2 !== size_log2) begin
            $display("ERROR [Test %0d] out_tu_size_log2 mismatch! Actual=%0d Expected=%0d", test_id, out_tu_size_log2, size_log2);
            err_count = err_count + 1;
            test_fail = 1;
        end

        if (out_fwd_inv_n !== fwd) begin
            $display("ERROR [Test %0d] out_fwd_inv_n mismatch! Actual=%b Expected=%b", test_id, out_fwd_inv_n, fwd);
            err_count = err_count + 1;
            test_fail = 1;
        end

        if (!test_fail) pass_tests = pass_tests + 1;
        total_tests = total_tests + 1;
    end
    endtask

    initial begin
        clk = 0;
        rst_n = 0;
        fwd_inv_n = 1;
        tu_size_log2 = 2;
        in_valid = 0;
        in_data = 0;
        out_ready = 1;
        total_tests = 0;
        pass_tests = 0;
        err_count = 0;

        #50;
        rst_n = 1;
        #20;

        $display("================================================================================");
        $display("Starting Comprehensive 2D Transform Verification of Row-Serial dct_top.v");
        $display("================================================================================");

        // Test 1: 4x4_fwd_DC
        check_2d_transform(1, 1'b1, 3'd2, 16384', 16384');
        // Test 2: 4x4_fwd_Impulse00
        check_2d_transform(2, 1'b1, 3'd2, 16384', 16384');
        // Test 3: 4x4_fwd_Ramp
        check_2d_transform(3, 1'b1, 3'd2, 16384', 16384');
        // Test 4: 4x4_fwd_Random
        check_2d_transform(4, 1'b1, 3'd2, 16384', 16384');
        // Test 5: 4x4_inv_DC
        check_2d_transform(5, 1'b0, 3'd2, 16384', 16384');
        // Test 6: 4x4_inv_Impulse00
        check_2d_transform(6, 1'b0, 3'd2, 16384', 16384');
        // Test 7: 4x4_inv_Ramp
        check_2d_transform(7, 1'b0, 3'd2, 16384', 16384');
        // Test 8: 4x4_inv_Random
        check_2d_transform(8, 1'b0, 3'd2, 16384', 16384');
        // Test 9: 8x8_fwd_DC
        check_2d_transform(9, 1'b1, 3'd3, 16384', 16384');
        // Test 10: 8x8_fwd_Impulse00
        check_2d_transform(10, 1'b1, 3'd3, 16384', 16384');
        // Test 11: 8x8_fwd_Ramp
        check_2d_transform(11, 1'b1, 3'd3, 16384', 16384');
        // Test 12: 8x8_fwd_Random
        check_2d_transform(12, 1'b1, 3'd3, 16384', 16384');
        // Test 13: 8x8_inv_DC
        check_2d_transform(13, 1'b0, 3'd3, 16384', 16384');
        // Test 14: 8x8_inv_Impulse00
        check_2d_transform(14, 1'b0, 3'd3, 16384', 16384');
        // Test 15: 8x8_inv_Ramp
        check_2d_transform(15, 1'b0, 3'd3, 16384', 16384');
        // Test 16: 8x8_inv_Random
        check_2d_transform(16, 1'b0, 3'd3, 16384', 16384');
        // Test 17: 16x16_fwd_DC
        check_2d_transform(17, 1'b1, 3'd4, 16384', 16384');
        // Test 18: 16x16_fwd_Impulse00
        check_2d_transform(18, 1'b1, 3'd4, 16384', 16384');
        // Test 19: 16x16_fwd_Ramp
        check_2d_transform(19, 1'b1, 3'd4, 16384', 16384');
        // Test 20: 16x16_fwd_Random
        check_2d_transform(20, 1'b1, 3'd4, 16384', 16384');
        // Test 21: 16x16_inv_DC
        check_2d_transform(21, 1'b0, 3'd4, 16384', 16384');
        // Test 22: 16x16_inv_Impulse00
        check_2d_transform(22, 1'b0, 3'd4, 16384', 16384');
        // Test 23: 16x16_inv_Ramp
        check_2d_transform(23, 1'b0, 3'd4, 16384', 16384');
        // Test 24: 16x16_inv_Random
        check_2d_transform(24, 1'b0, 3'd4, 16384', 16384');
        // Test 25: 32x32_fwd_DC
        check_2d_transform(25, 1'b1, 3'd5, 16384', 16384');
        // Test 26: 32x32_fwd_Impulse00
        check_2d_transform(26, 1'b1, 3'd5, 16384', 16384');
        // Test 27: 32x32_fwd_Ramp
        check_2d_transform(27, 1'b1, 3'd5, 16384', 16384');
        // Test 28: 32x32_fwd_Random
        check_2d_transform(28, 1'b1, 3'd5, 16384', 16384');
        // Test 29: 32x32_inv_DC
        check_2d_transform(29, 1'b0, 3'd5, 16384', 16384');
        // Test 30: 32x32_inv_Impulse00
        check_2d_transform(30, 1'b0, 3'd5, 16384', 16384');
        // Test 31: 32x32_inv_Ramp
        check_2d_transform(31, 1'b0, 3'd5, 16384', 16384');
        // Test 32: 32x32_inv_Random
        check_2d_transform(32, 1'b0, 3'd5, 16384', 16384');

        $display("\n================================================================================");
        $display("  2D TRANSFORM VERIFICATION COMPLETE: Total=%0d  Passed=%0d  Errors=%0d", total_tests, pass_tests, err_count);
        if (err_count == 0) begin
            $display("  >>> ALL %0d 2D TEST CASES PASSED BIT-EXACTLY AGAINST HM 18.0! <<<", total_tests);
            $display("================================================================================\n");
            $finish;
        end else begin
            $display("  >>> VERIFICATION FAILED WITH %0d ERRORS! <<<", err_count);
            $display("================================================================================\n");
            $fatal(1);
        end
    end

endmodule
